components.css:
.ds-seg{display:inline-flex;border:1px solid var(--rule-2,#364154);border-radius:8px;overflow:hidden;background:var(--ink-2,#151b25)}
.ds-seg button{appearance:none;background:transparent;color:var(--paper-2,#c5beae);border:0;padding:7px 12px;font-family:var(--mono,monospace);font-size:.82rem;cursor:pointer;border-right:1px solid var(--rule,#2a3344);display:flex;align-items:center;gap:7px;transition:background .12s,color .12s}
.ds-seg button:last-child{border-right:0}
.ds-seg button:hover{color:var(--paper,#ece5d6);background:rgba(236,229,214,.04)}
.ds-seg button:active{background:var(--ink-3,#1b2230)}
.ds-seg button[aria-pressed="true"]{background:var(--ink-3,#1b2230);color:var(--paper,#ece5d6)}
.ds-seg button:focus-visible{outline:2px solid var(--paper,#ece5d6);outline-offset:-2px}
.ds-seg-dot{width:7px;height:7px;border-radius:50%;background:var(--teal,#54a99c)}
.ds-seg button[aria-pressed="false"] .ds-seg-dot{background:var(--paper-3,#8f8a7c);opacity:.7}
